"""Standalone updater UI, served only after cookie + Admin DB authentication.

Remains reachable through its explicit Caddy route while the app is fenced.
No root command endpoint is exposed: actions use the existing app admin API.
"""
import secrets

SCRIPT=r'''
const $=id=>document.getElementById(id);
const labels={queued:'Menunggu giliran',preflight:'Memeriksa kesiapan',downloading:'Mengunduh aplikasi',preparing:'Menyiapkan aplikasi',backing_up:'Mencadangkan dan memverifikasi data',migrating:'Menyesuaikan database',activating:'Mengaktifkan aplikasi',verifying:'Memeriksa hasil',succeeded:'Update berhasil',failed:'Update belum berhasil',recovery_required:'Perlu bantuan operator',rolling_back:'Memulihkan aplikasi sebelumnya',rolled_back:'Aplikasi sebelumnya dipulihkan'};
const reasons={worker_upgrade_in_progress:'Pemasangan updater belum selesai. Operator perlu merekonsiliasi pemasangannya.',payment_webhook_not_supported:'Provider pembayaran otomatis belum memiliki jalur webhook yang terverifikasi untuk upgrade ini. Hubungi operator.',worker_upgrade_required:'Operator perlu memasang worker terbaru satu kali.',upgrade_path_unsupported:'Belum ada jalur upgrade yang disetujui dari versi toko ini. Hubungi operator.',operator_migration_required:'Metadata migrasi yang disetujui belum tersedia. Hubungi operator.',installation_not_in_pilot:'Toko belum termasuk kelompok pemasangan yang disetujui.',carrier_work_pending:'Permintaan J&T belum selesai atau hasilnya belum pasti. Operator perlu merekonsiliasinya.',active_requests_pending:'Permintaan toko masih berjalan. Update ditahan agar transaksi tetap aman.',schema_drift:'Struktur database berbeda dari baseline yang didukung.',migration_history:'Riwayat migrasi berbeda atau belum selesai. Operator perlu memeriksanya.',local_customization:'Ada perubahan khusus pada aplikasi yang perlu ditinjau operator.',active_source_mismatch:'Aplikasi yang berjalan berbeda dari sumber rilis.',insufficient_disk:'Ruang penyimpanan belum cukup.',insufficient_resources:'Sumber daya server belum cukup.',proxy_review_required:'Konfigurasi proxy perlu ditinjau operator agar domain lain tetap terlindungi.',catalog_unavailable:'Katalog belum dapat diverifikasi. Coba periksa lagi.',policy_expired_or_invalid:'Metadata migrasi kedaluwarsa atau tidak valid. Operator perlu menerbitkan metadata baru.',external_work_review_required:'Hasil pekerjaan server belum dapat dipastikan. Operator harus memeriksanya.',preflight_unavailable:'Pemeriksaan kesiapan belum berhasil. Coba lagi atau hubungi operator.'};
let state=null,pending=false,key='',keySha='';
const active=j=>j&&!['succeeded','failed','rolled_back'].includes(j.state);
function render(d){state=d;const j=d.jobs?.[0],running=active(j)||!!d.workerUpgradeState,a=d.availability;
 $('installed').textContent=d.installedVersion||'Belum terdeteksi';
 $('latest').textContent=a?.latest?.version||d.catalogLatest?.version||'Belum diperiksa';
 $('worker').textContent='Updater v'+(d.updaterVersion||'—');
 $('checked').textContent=d.checkedAt?new Date(d.checkedAt*1000).toLocaleString('id-ID'):'Belum diperiksa';
 $('availability').textContent=a?.state==='current'?'Versi toko sudah terkini untuk kanal ini.':a?.state==='available'?'Update siap dipasang.':a?.state==='blocked'?(reasons[a.reason]||'Update memerlukan pemeriksaan operator.'):reasons.catalog_unavailable;
 $('notes').textContent=d.release?.notes||a?.latest?.notes||'';
 $('check').disabled=pending||running;$('start').hidden=!d.release||running;$('start').disabled=pending;
 $('next').textContent=d.release&&a?.latest?.version!==d.release.version?'Pasang '+d.release.version+' terlebih dahulu, lalu periksa kembali.':'';
 $('job').hidden=!j;if(j){$('phase').textContent=labels[j.state]||'Memeriksa status';$('ref').textContent='Referensi proses: '+j.id;
 $('detail').textContent=j.state==='recovery_required'?'Update berikutnya dikunci. Data tidak dipulihkan otomatis dari backup lama. Hubungi operator dengan referensi proses di atas.':j.detail?.error?(reasons[j.detail.error]||'Operator dapat memeriksa catatan proses.'):j.state==='succeeded'?'Versi '+(j.detail?.activeVersion||j.version)+' telah aktif.':'';
 $('download').textContent=j.state==='downloading'&&j.detail?.total?'Unduhan '+Math.floor(100*(j.detail.downloaded||0)/j.detail.total)+'%':'';
 $('reload').hidden=j.state!=='succeeded';}
 $('history').replaceChildren();for(const item of d.jobs||[]){const li=document.createElement('li');li.textContent='v'+item.version+' · '+(labels[item.state]||item.state);$('history').append(li);}}
async function poll(){try{const r=await fetch('/api/local-updater/session-status',{credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(8000)});if(r.status===401||r.status===403){$('network').textContent='Sesi berakhir atau akses berubah. Masuk kembali untuk melihat status.';return;}if(!r.ok)throw Error();render(await r.json());$('network').textContent='';}catch{$('network').textContent='Koneksi status terputus. Ini tidak membatalkan update.';}setTimeout(poll,3000);}
async function command(action){if(pending)return;pending=true;$('check').disabled=true;$('start').disabled=true;$('message').textContent='';try{const sha=state?.release?.sha;if(action==='start'&&(!key||keySha!==sha)){key=crypto.randomUUID();keySha=sha;}const r=await fetch('/api/v1/admin/updater',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(action==='start'?{action,sha,requestKey:key}:{action}),signal:AbortSignal.timeout(15000)});const result=await r.json();if(!r.ok||!result.success)throw Error(result.error?.message||'Permintaan belum berhasil.');render(result.data);if(action==='start')key='';}catch(e){$('message').textContent=e.message||'Periksa status sebelum mencoba kembali.';}finally{pending=false;if(state)render(state);}}
$('check').addEventListener('click',()=>command('check'));$('start').addEventListener('click',()=>command('start'));$('reload').addEventListener('click',()=>location.reload());poll();
'''


def page():
    nonce=secrets.token_urlsafe(24)
    html='''<!doctype html><html lang="id"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Update Versi · Hubify Seller</title>
<style>*{box-sizing:border-box}body{margin:0;background:#fafafa;color:#111;font:16px/1.5 system-ui,sans-serif}main{max-width:760px;margin:auto;padding:24px 16px 48px}a{color:inherit}h1{font-size:28px;margin:20px 0 4px}h2{font-size:18px;margin:0}p{margin:8px 0}.muted,small{color:#52525b}.card{background:#fff;border:1px solid #e4e4e7;border-radius:16px;padding:20px;margin-top:16px}.versions{display:flex;gap:32px;flex-wrap:wrap}.value{display:block;font-size:28px;font-weight:700;font-variant-numeric:tabular-nums}button{font:inherit;min-height:44px;border-radius:10px;padding:10px 18px;border:1px solid #d4d4d8;background:#fff;color:#111;cursor:pointer;transition:transform 120ms ease-out}button:active{transform:scale(.98)}button:focus-visible,a:focus-visible{outline:2px solid #111;outline-offset:3px}button.primary{background:#111;color:#fff;border-color:#111}button:disabled{opacity:.5;cursor:default}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:16px}#notes{white-space:pre-wrap;font-size:14px}#availability{background:#f4f4f5;border-radius:10px;padding:12px}#ref{overflow-wrap:anywhere}li{padding:8px 0}ul{padding-left:20px}@media(max-width:480px){.actions button{width:100%}.card{padding:16px}}@media(prefers-reduced-motion:reduce){button{transition:none}}</style>
<main><a href="/admin">← Kembali ke dashboard</a><h1>Update Versi</h1><p class="muted">Perbarui toko dan pantau prosesnya di sini.</p>
<section class="card"><p id="worker" class="muted"></p><div class="versions"><div><small>Versi terpasang</small><strong id="installed" class="value">—</strong></div><div><small>Versi terbaru di katalog</small><strong id="latest" class="value">—</strong></div></div><p><small>Terakhir diperiksa: <span id="checked">Belum diperiksa</span></small></p><p id="availability" role="status">Menghubungi updater…</p><p id="next"></p><p id="notes"></p><div class="actions"><button id="check" type="button">Cek pembaruan</button><button id="start" class="primary" type="button" hidden>Update sekarang</button></div><p id="message" role="alert"></p><p id="network" role="status"></p></section>
<section id="job" class="card" aria-live="polite" hidden><h2 id="phase"></h2><p id="download"></p><p id="ref" class="muted"></p><p id="detail"></p><button id="reload" type="button" hidden>Muat ulang dashboard</button></section><section class="card"><h2>Riwayat update</h2><ul id="history"></ul></section><p class="muted"><small>Proses tetap berjalan saat halaman ditutup. Anda dapat membuka kembali halaman ini, termasuk saat aplikasi sedang diperbarui.</small></p></main><script nonce="NONCE">SCRIPT</script></html>'''
    return html.replace('NONCE',nonce).replace('SCRIPT',SCRIPT).encode(),nonce
